import{_ as e,o as a,c as p,a2 as d}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"HTTP Request Methods (HTTP 请求方法)","description":"","frontmatter":{},"headers":[],"relativePath":"httpRequestMethodsGlossary.md","filePath":"httpRequestMethodsGlossary.md","lastUpdated":1679401943000}'),s={name:"httpRequestMethodsGlossary.md"};function o(h,t,T,r,i,n){return a(),p("div",null,[...t[0]||(t[0]=[d('<h1 id="http-request-methods-http-请求方法" tabindex="-1">HTTP Request Methods (HTTP 请求方法)</h1><p>HTTP 定义了一组请求方法, 以表明要对给定资源执行的操作.</p><blockquote><p>参阅: <a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Methods" target="_blank" rel="noreferrer">MDN</a></p></blockquote><hr><h2 id="get" tabindex="-1">GET</h2><p>GET 方法请求一个指定资源的表示形式, 使用 GET 的请求应该只被用于获取数据.</p><h2 id="head" tabindex="-1">HEAD</h2><p>HEAD 方法请求一个与 GET 请求的响应相同的响应, 但没有响应体.</p><h2 id="post" tabindex="-1">POST</h2><p>POST 方法用于将实体提交到指定的资源, 通常导致在服务器上的状态变化或副作用.</p><h2 id="put" tabindex="-1">PUT</h2><p>PUT 方法用请求有效载荷替换目标资源的所有当前表示.</p><h2 id="delete" tabindex="-1">DELETE</h2><p>DELETE 方法删除指定的资源.</p><h2 id="connect" tabindex="-1">CONNECT</h2><p>CONNECT 方法建立一个到由目标资源标识的服务器的隧道.</p><h2 id="options" tabindex="-1">OPTIONS</h2><p>OPTIONS 方法用于描述目标资源的通信选项.</p><h2 id="trace" tabindex="-1">TRACE</h2><p>TRACE 方法沿着到目标资源的路径执行一个消息环回测试.</p><h2 id="patch" tabindex="-1">PATCH</h2><p>PATCH 方法用于对资源应用部分修改.</p>',22)])])}const c=e(s,[["render",o]]);export{_ as __pageData,c as default};
